import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { LeaveApplicationComponent } from './components/leave-application/leave-application.component';
import { LeaveTrackerComponent } from './components/leave-tracker/leave-tracker.component';

const routes: Routes = [
  { path: '', component: LeaveApplicationComponent }, // Default route
  { path: 'leave-tracker', component: LeaveTrackerComponent } // ✅ Add Leave Tracker Route
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule { }
